# -*- coding: utf-8 -*-
"""英语 · 全部知识点。缩进即层级：章 → 节 → 知识点。"""
NAME = "英语"

TREE = {
    "第一板块 词汇": {
        "1.1 构词法与词性": [
            {"t": "派生法：前后缀", "body": "常见前缀：**un-、in-、dis-、non- 表否定；re- 表重复**；pre- 表预先；post- 表之后；inter- 表之间。\n常见后缀：-tion、-ment、-ness 构成名词；-able、-ful、-less 构成形容词；-ly 构成副词；-ize、-ify 构成动词。\n掌握前后缀可推测生词含义。\n注意词性变化后读音与拼写的变化。\n同一词根加不同词缀意义不同。"},
            {"t": "合成法与转化法", "body": "合成法：两个或多个词合成新词，如 blackboard、well-known。\n合成形容词常由副词+过去分词构成，如 well-prepared。\n转化法：词形不变而词性改变，如 water（名词→动词）。\n转化后词义常与原义相关。\n**构词法知识有助于阅读中猜测词义**。"},
            {"t": "词性与句子成分", "body": "名词作主语、宾语、表语；动词作谓语。\n形容词修饰名词或作表语；副词修饰动词、形容词或全句。\n介词后接名词或动名词。\n**判断词性要结合句法位置**。\n词性判断是语法填空的核心技巧。"},
            {"t": "常见前缀的含义", "body": "否定前缀：un-、in-、im-、il-、ir-、dis-、non-（如 unable、impossible、dislike）。\n方向与程度：re-（再）、pre-（预先）、post-（之后）、sub-（下）、super-（超）、over-（过度）、under-（不足）。\n人与关系：co-（共同）、anti-（反对）、auto-（自动）、inter-（相互）。\n数量：mono-（单）、bi-（双）、tri-（三）、multi-（多）。\n**判断词义时先剥离前缀，再结合词根推断**。"},
            {"t": "常见后缀与词性判断", "body": "名词后缀：-tion、-ment、-ness、-ity、-ance、-ship、-er/-or（人）。\n形容词后缀：-ful、-less、-ous、-able、-ive、-al、-ic。\n动词后缀：-ize/-ise、-ify、-en。\n副词后缀：-ly（多数副词）。\n**语法填空中若空格前有冠词或形容词，多填名词；有系动词多填形容词**。"},
        ],
        "1.2 高频短语与词语辨析": [
            {"t": "动词短语搭配", "body": "常见短语：account for（解释）、break down（出故障）、carry out（执行）、come up with（想出）。\ngive up、give in、give away、give off 意义各不相同。\nturn to、turn up、turn down、turn out 要区分。\n**短语动词的宾语位置需注意（代词放中间）**。\n固定搭配是完形填空的常考点。"},
            {"t": "近义词辨析", "body": "**affect 与 effect：前者动词影响，后者名词效果**。\nrise 不及物，raise 及物。\naccept（主动接受）与 receive（收到）。\nbesides（除…还有）与 except（除…之外）。\nelder 与 older：前者只用于人且作定语。"},
            {"t": "介词与固定搭配", "body": "时间介词：in 用于年月季节，on 用于具体某天，at 用于时刻。\n位置介词：in、on、at 的空间感不同。\n常见搭配：be interested in、be good at、be afraid of。\n介词后接名词、代词或动名词。\n**介词搭配错误是语法填空的高频失分点**。"},
            {"t": "易混动词辨析", "body": "raise（及物，举起、提高）与 rise（不及物，上升）易混。\n**lay（放置，过去式 laid）与 lie（躺，过去式 lay；说谎，lied）易混**。\nspend 人作主语，cost 物作主语，take 用 it 作形式主语。\nborrow（借入）与 lend（借出）方向相反。\n记易混词要结合例句和搭配，如 raise one's hand、the sun rises。"},
            {"t": "一词多义的辨析", "body": "英语中许多词有多种含义，要根据语境判断。\n如 get 可表示得到、变得、到达等。\ntake 可表示拿、花费、乘坐、服用等。\nrun 可表示跑、经营、流动等。\n**词义辨析要结合上下文，不能死记单一意思**。\n积累一词多义有助于提高阅读和完形能力。"},
            {"t": "高频名词与形容词搭配", "body": "名词搭配要注意固定介词：solution to（……的解决办法）、access to（通往/使用权）、effect on（对……的影响）、reason for（……的原因）、increase in（……的增长）。\n形容词搭配：be aware of、be capable of、be responsible for、be similar to、be different from、be keen on。\n动词搭配：make a decision、take measures、pay attention to、gain experience、draw a conclusion。\n**写作中把 make、take、have、pay 这些高频动词与名词搭配记熟，比记单个名词更实用**。\n辨析时要注意搭配对象不同，如 high 修饰高度，tall 修饰人或细长物。"},
        ],
    },
    "第二板块 语法": {
        "2.1 时态与语态": [
            {"t": "常用时态", "body": "一般现在时：表习惯、真理、客观事实。\n一般过去时：表过去发生的动作，常与明确过去时间连用。\n**现在完成时：表过去动作对现在的影响，或持续到现在**。\n过去完成时：表过去某一时间之前完成的动作，即过去的过去。\n将来时：will do 表意愿或预测，be going to 表计划。"},
            {"t": "被动语态", "body": "构成：be+过去分词，时态体现在 be 上。\n只有及物动词才有被动语态。\n**happen、occur、belong to 等不及物动词无被动**。\n被动语态常用于不知道或不必说明施动者的情况。\n情态动词被动：must be done、should have been done。"},
            {"t": "主谓一致", "body": "语法一致：主语单复数决定谓语形式。\n意义一致：family、team 等集体名词视语境而定。\n**就近原则：either…or、neither…nor、there be 句型**。\n不定式、动名词、从句作主语视为单数。\n注意 the number of 与 a number of 的区别。"},
            {"t": "完成时态的用法", "body": "现在完成时表示过去发生的动作对现在造成影响或持续到现在。\n结构为 \\frac{have}{has} done，常与 since、for、already、yet 连用。\n过去完成时表示「过去的过去」，结构为 had done。\n**现在完成时强调影响或结果，一般过去时只强调动作发生在过去**。\n延续性动词才能与一段时间连用，如 have had 而非 have bought。"},
            {"t": "一般过去时与现在完成时的区别", "body": "一般过去时只强调动作发生在过去，与现在没有联系。\n现在完成时强调过去的动作对现在造成的影响或结果。\n**有明确过去时间状语（yesterday、last year、ago）用一般过去时**。\njust、already、yet、so far 等常用现在完成时。\nSince 引导时间状语从句时，主句用现在完成时。"},
            {"t": "将来时的表达方式", "body": "一般将来时用 will + 动词原形，表示将来的动作或状态。\n**be going to 表示打算或根据迹象判断将要发生**。\nbe doing 可表示按计划安排将要发生的动作。\nbe to do 表示按计划、安排将要发生。\n一般现在时也可表示按时刻表将要发生的动作。"},
            {"t": "进行时态的用法", "body": "**现在进行时表示说话时正在进行的动作**。\n结构为 be + 现在分词。\n也可表示按计划将要发生的动作，如 I am leaving tomorrow。\n过去进行时表示过去某一时刻正在进行的动作。\n现在完成进行时表示从过去持续到现在的动作。"},
            {"t": "过去完成时", "body": "过去完成时表示在过去某一时刻之前已经完成的动作。\n结构为 had + 过去分词。\n常与 by、before、when 等时间状语连用。\n**表示「过去的过去」，强调动作的先后顺序**。\n在宾语从句中，主句用过去时，从句可用过去完成时。"},
            {"t": "现在完成进行时", "body": "现在完成进行时表示从过去持续到现在的动作。\n结构为 \\frac{have}{has} been + 现在分词。\n强调动作的持续性和未完成性。\n如 I have been reading for two hours。\n**与现在完成时的区别：完成进行时强调持续过程**。"},
            {"t": "一般现在时的用法", "body": "一般现在时表示经常性、习惯性的动作或状态。\n也表示客观真理和事实。\n如 The earth moves around the sun。\n**第三人称单数动词加 s 或 es**。\n一般现在时还可表示按时刻表将要发生的动作。"},
            {"t": "过去进行时", "body": "**过去进行时表示过去某时刻正在进行的动作**。\n结构为 \\frac{was}{were} + 现在分词。\n常与 when、while 连用。\n如 I was reading when he came。\n过去进行时强调动作的进行状态。"},
            {"t": "一般过去时的用法", "body": "一般过去时表示过去发生的动作或状态。\n结构为动词过去式。\n常与 yesterday、last year、ago 连用。\n**表示过去经常发生的动作用 used to**。\n一般过去时强调动作发生在过去。"},
            {"t": "将来进行时", "body": "**将来进行时表示将来某时刻正在进行的动作**。\n结构为 will be + 现在分词。\n如 I will be studying at 8 tomorrow。\n也表示按计划将要发生的动作。\n将来进行时强调将来的进行状态。"},
            {"t": "过去将来时", "body": "**过去将来时表示从过去看将要发生的动作**。\n结构为 would + 动词原形。\n常用于宾语从句中。\n如 He said he would come。\n过去将来时与一般将来时对应。"},
            {"t": "时态的一致性", "body": "主从句时态要呼应。\n**主句过去时，从句用过去时态**。\n主句现在时，从句根据实际用时态。\n客观真理用一般现在时，即使主句是过去时。\n时态一致是语法的重要规则。\n宾语从句注意陈述语序与时态配合。"},
            {"t": "将来完成时", "body": "将来完成时表示将来某时刻前已完成的动作。\n**结构为 will have + 过去分词**。\n常与 by 引导的时间状语连用。\n如 I will have finished by then。\n将来完成时强调动作的完成。"},
            {"t": "时态的判定信号词", "body": "**时态题先找时间信号词，再定动作状态**。\nalready、just、yet、so far、in the past few years 常配现在完成时；ago、last week、in 1990 常配一般过去时。\nnow、at present、look 提示现在进行时；by the end of last year 提示过去完成时；by the end of next year 提示将来完成时。\n时间状语从句与条件状语从句中，主将从现：主句用将来时，从句用一般现在时。\n没有信号词时看上下文语境，特别注意两个动作的先后关系。"},
            {"t": "虚拟语气中的时态", "body": "虚拟语气按其所在时间分三类，时态整体向前推一步。\n**与现在事实相反：从句用过去式（be 用 were），\\frac{could}{might} do**。\n与过去事实相反：从句用 had done，主句用 would have done。\n与将来事实相反：从句用 were to do 或 should do，主句用 would do。\n名词性从句中，suggest、demand、insist、require 等表示要求建议时，从句用 should do 且 should 可省略。\nwish 后的从句同样按时间前推，if only 用法相同。"},
        ],
        "2.2 非谓语动词": [
            {"t": "不定式", "body": "形式：to do、to be done、to have done。\n常作目的状语、宾语、定语、主语。\n**在 make、let、have 后作宾补时省略 to**。\n不定式表将来或未发生的动作。\n某些形容词后接不定式（glad to do）。"},
            {"t": "动名词", "body": "形式：doing、being done、having done。\n可作主语、宾语、表语、定语。\n**介词后必须用动名词**。\n常见只接动名词的动词：enjoy、finish、practise、mind、avoid。\n动名词作主语时谓语用单数。"},
            {"t": "分词", "body": "**现在分词 doing 表主动或进行；过去分词 done 表被动或完成**。\n作定语时单个分词前置，分词短语后置。\n作状语时其逻辑主语应与句子主语一致。\n某些动词的现在分词表示事物特征（interesting），过去分词表示人的感受（interested）。\n作宾补时 see sb doing（正在进行）与 see sb do（全过程）不同。"},
            {"t": "独立主格与with复合结构", "body": "独立主格：名词/代词+分词/不定式/形容词，与主句无语法连接。\n**with 复合结构：with+宾语+宾补，常作伴随状语**。\n示例：With the work finished, he went home。\n这种结构中宾补与宾语有逻辑关系。\n是写作提分的有效句式。"},
            {"t": "不定式与动名词的区别", "body": "不定式 to do 常表目的、将来，动名词 doing 常表习惯、一般。\n**\\frac{forget}{remember} to do 表示忘记/记得要做（未做），doing 表示忘记/记得做过**。\nstop to do 停下来去做另一件事，stop doing 停止正在做的事。\nwant、hope、decide、plan 后接不定式，enjoy、finish、mind 后接动名词。\n介词后接动名词，如 be good at doing。"},
            {"t": "非谓语动词作定语", "body": "非谓语动词作定语时要注意与所修饰词的主被动关系和时态关系。\n**现在分词 doing 表主动、进行，过去分词 done 表被动、完成**。\n不定式 to do 表将来，常修饰抽象名词。\nThe boy standing there is my brother（主动进行）。\nThe bridge built last year is strong（被动完成）。"},
            {"t": "非谓语动词作宾语", "body": "有些动词后接不定式，有些后接动名词。\nwant、hope、decide、plan 后接不定式。\nenjoy、finish、mind、avoid 后接动名词。\n**remember、forget、stop 后接不定式和动名词意义不同**。\n介词后接动名词，如 be interested in doing。"},
            {"t": "非谓语动词作状语", "body": "非谓语动词作状语表示时间、原因、条件、伴随等。\n现在分词作状语表主动，过去分词作状语表被动。\n不定式作状语常表目的、结果。\n**逻辑主语要与句子主语一致**。\n独立主格结构有自己的逻辑主语，如 The work done, he left。"},
            {"t": "非谓语动词作主语", "body": "不定式和动名词可作主语。\n不定式作主语表具体动作。\n**动名词作主语表一般习惯**。\n常用 it 作形式主语。\n如 To learn English is important。"},
            {"t": "非谓语动词的否定", "body": "**非谓语动词的否定在非谓语前加 not**。\n如 not to do、not doing、not done。\nnot knowing what to do。\n否定形式要紧跟非谓语。\n注意否定位置。"},
            {"t": "非谓语动词作宾语补足语", "body": "非谓语动词可作宾语补足语。\n感官动词后接现在分词或不定式。\n**使役动词后接不定式省略 to**。\nhave 后接过去分词表被动。\n选择看与宾语的关系。"},
            {"t": "非谓语动词的逻辑主语", "body": "非谓语动词的逻辑主语要与句子主语一致。\n不一致时用独立主格结构。\n现在分词逻辑主语是动作发出者。\n过去分词逻辑主语是动作承受者。\n**判断逻辑主语是使用非谓语的关键**。"},
            {"t": "非谓语动词的时态语态", "body": "非谓语动词有各种时态和语态形式。\ndoing 表主动进行，done 表被动完成。\nto do 表将来，to be done 表将来被动。\nhaving done 表主动完成。\nhaving been done 表被动完成。\n**选择形式看与逻辑主语的关系**。"},
            {"t": "非谓语的解题三步", "body": "第一步判断句子是否已有谓语：**若已有谓语，则另一个动词必须变为非谓语**。\n第二步确定逻辑主语：非谓语的逻辑主语通常是句子的主语或它修饰的名词。\n第三步判定关系与时间：主动用 doing，被动用 done，目的或将来用 to do，先发生用 having done。\n固定搭配要单独记，如 be used to doing（习惯于）、used to do（过去常常）、be devoted to doing。\n最后检查是否与句中其他成分重复或矛盾。"},
        ],
        "2.3 从句": [
            {"t": "定语从句", "body": "限制性定语从句修饰先行词，不可缺少。\n非限制性定语从句用逗号隔开，不能修饰整个句子时也需注意。\n关系代词：who、whom、whose、which、that。\n关系副词：when、where、why，相当于介词+which。\n**介词后关系代词只能用 whom 或 which**。"},
            {"t": "同位语从句与定语从句的区别", "body": "**同位语从句说明先行词的内容，定语从句修饰先行词**。\n同位语从句引导词 that 不作成分，定语从句 that 作成分。\n同位语从句先行词常是 news、fact、idea、hope 等抽象名词。\n判断方法：看从句与先行词的关系是说明还是修饰。\n同位语从句的 that 不能省略。"},
            {"t": "状语从句的类型与连词", "body": "时间：when、while、as、before、after、until、as soon as。\n条件：if、unless、as long as、in case。\n让步：although、though、even if、while（虽）。\n原因：because、since、as；结果：so...that；目的：so that、in order that。\n**注意主将从现：时间与条件状语从句中一般现在时代替将来时**。"},
            {"t": "名词性从句的语序与引导词", "body": "名词性从句包括主语从句、宾语从句、表语从句、同位语从句，**一律用陈述语序**。\nthat 无实义只起连接作用，在宾语从句中可省略，其他三种从句一般不可省。\nwhether 与 if 都表「是否」，但介词后、句首主语从句、与 or not 直接连用时只能用 whether。\nwhat 在从句中充当成分（主语、宾语、表语），that 不作成分，这是最常考的区别。\n同位语从句解释前面抽象名词的内容（news、fact、idea、hope），定语从句则修饰限定该名词，注意区分。"},
        ],
        "2.4 特殊句式": [
            {"t": "倒装句", "body": "完全倒装：地点状语置于句首且谓语动词为不及物动词。\n**部分倒装：否定词（never、hardly、little）置于句首**。\nonly+状语置于句首时\\frac{neither}{nor} 引导的倒装表同样或也不。\nnot until 置于句首时主句用倒装。"},
            {"t": "强调句与省略", "body": "强调句句型：It \\frac{is}{was}+被强调部分+\\frac{that}{who}+其他。\n强调人可用 who 或 that，强调其他用 that。\n判断是否为强调句可用**去掉 It is…that 看句子是否完整**。\n省略常见于状语从句、不定式、比较结构。\n省略要保证句意明确、结构完整。"},
            {"t": "it 的用法与反义疑问", "body": "it 可作形式主语、形式宾语、指代时间天气距离。\n**反义疑问句遵循前肯后否、前否后肯的原则**。\n含 never、hardly 等否定词的句子视为否定。\nI think 等主句的反义疑问与从句一致（主句为 I 时）。\n祈使句的反义疑问用 will you。"},
            {"t": "虚拟语气的用法", "body": "虚拟语气表示与事实相反的假设。\n与现在事实相反：if + 过去式，主句 would do。\n**与过去事实相反：if + had done，主句 would have done**。\n与将来事实相反：if + were to \\frac{do}{should} do，主句 would do。\nwish 后的宾语从句用虚拟语气。"},
            {"t": "主谓一致的规则", "body": "主谓一致是指谓语动词与主语在人称和数上保持一致。\n单数主语用单数谓语，复数主语用复数谓语。\n不定式、动名词、从句作主语时谓语用单数。\n**就近原则：either...or、neither...nor 就近一致**。\n集合名词 family 等可指整体（单数）或成员（复数）。"},
            {"t": "省略句的用法", "body": "省略句是在不影响理解的前提下省略某些成分。\n状语从句省略：While (I was) reading, I fell asleep。\n比较状语从句省略：He runs faster than I (do)。\n省略使句子简洁，但要注意语义明确。\n**省略要避免歧义，保持逻辑清晰**。"},
            {"t": "祈使句", "body": "祈使句表示请求、命令、建议。\n**以动词原形开头**。\n否定在句首加 Don't。\n如 Sit down / Don't be late。\n祈使句主语常省略。"},
            {"t": "感叹句", "body": "感叹句表达强烈情感。\n用 what 或 how 引导。\nWhat a beautiful flower!。\nHow beautiful the flower is!。\n**感叹句用陈述语序**。"},
            {"t": "there be 与省略句", "body": "there be 句型表示「存在」，be 的单复数与后面第一个名词一致（就近原则）。\nthere be 还可与情态动词、seem、happen 连用，如 there seems to be、there must be。\n**注意 there be 与 have 的区别：there be 表存在，have 表所属**。\n省略句常见于状语从句（When asked, he kept silent）、并列句与比较结构（I like it better than she does）。\nso do I 与 \\frac{neither}{nor} do I 表示同上或同样不，注意助动词与前句保持一致。"},
        ],
    },
    "第三板块 题型策略": {
        "3.1 阅读理解": [
            {"t": "细节理解题", "body": "先读题干，确定关键词，再回原文定位。\n**注意同义替换是正确答案的常见形式**。\n排除偷换时间、地点、对象、程度的选项。\n部分题需跨段整合信息。\n顺序原则：题目顺序与文章顺序基本一致。"},
            {"t": "主旨大意与推理判断", "body": "**主旨题看首段、末段与各段首句**。\n标题要涵盖全文且简洁有吸引力。\n避免选择过于具体的细节或过于宽泛的选项。\n推理判断要基于原文，不能过度推断。\n态度题注意作者用词的褒贬倾向。"},
            {"t": "词义猜测与篇章结构", "body": "词义猜测看上下文：定义、举例、同义反义、构词。\n**注意破折号、冒号后常是解释**。\n篇章结构题要把握文章的组织方式。\n注意逻辑连接词：however、therefore、moreover。\n七选五题要注意代词与关键词的呼应。"},
            {"t": "推理判断题的解题技巧", "body": "推理判断题要求根据原文信息进行合理推断，不能脱离原文。\n推断要有依据，选项必须能从原文推出。\n**注意 but、however 等转折词后的信息常是推断的关键**。\n推断作者态度看用词的感情色彩。\n选项若与原文直接矛盾或过度推断，都是错误项。"},
            {"t": "作者态度题的判断", "body": "作者态度题要求判断作者对某事物的态度或观点。\n找表达态度的形容词，如 positive、negative、critical。\n**注意转折词后的态度，常是作者真实态度**。\n区分作者态度和文中人物的态度。\n选项中的态度词要结合语境判断褒贬。"},
            {"t": "阅读速度的提升", "body": "提高阅读速度要扩大视幅，减少回读。\n**按意群阅读，不要逐词阅读**。\n先看题目再读文章，带着问题阅读。\n抓住关键词和主题句，跳过细节。\n平时多阅读，积累词汇，提高理解速度。"},
            {"t": "阅读理解的同义替换", "body": "阅读理解选项常对原文进行同义替换。\n识别同义替换是解题的关键。\n如 important→significant，big→large。\n注意词性变化和句式转换。\n**答案往往是原文的同义表达**。"},
            {"t": "阅读理解的干扰项特征", "body": "阅读理解干扰项有常见特征。\n偷换概念、张冠李戴。\n以偏概全、无中生有。\n过度推断、绝对化表述。\n**识别干扰项有助于排除错误选项**。\n选择与原文意思最相符的选项。"},
            {"t": "阅读理解的长难句分析", "body": "**长难句要抓住主干结构**。\n先找主语、谓语、宾语，划掉修饰成分。\n再分析从句和修饰成分：定语从句、状语从句、插入语。\n拆分长句，逐个理解，按意群阅读。\n遇到并列结构找 and、but、or 划分层次。\n理解长难句是阅读的关键。"},
            {"t": "阅读理解的题文顺序", "body": "阅读理解可先题后文或先文后题。\n先题后文带着问题阅读，效率高。\n先文后题整体把握后再答题，适合主旨题。\n**细节题回原文定位**，注意同义替换。\n主旨题通读后作答，关注首尾段和段首句。"},
            {"t": "七选五的解题步骤", "body": "先读首段与各段首句，把握文章结构与话题。\n再看选项中的线索词：代词、连接词、重复出现的名词。\n根据空格位置判断功能：段首多为概括句，段中为衔接句，段末为总结句。\n利用指代一致、逻辑一致（转折、因果、并列）排除干扰项。\n**选完后通读全文，检验语义与语法是否连贯**。"},
            {"t": "阅读理解的文章结构", "body": "阅读理解要把握文章结构。\n总分、分总、总分总结构。\n**每段有主题句**。\n理清结构有助于理解。\n把握段落间的逻辑关系。"},
            {"t": "推理判断题的常见设错", "body": "推理判断题的错项主要有四种：过度推断、无中生有、张冠李戴、偷换程度。\n过度推断是超出原文合理范围，如原文说某措施有帮助，选项说它是唯一办法。\n无中生有是选项信息原文完全没提，常见于因果关系的强行添加。\n张冠李戴是把 A 的观点安到 B 身上，或把研究者的看法说成作者的看法。\n偷换程度是把 sometimes 换成 always、把 may 换成 must。\n**做题时坚持「一步推理」原则**：答案必须能由原文直接推出，不需要额外常识补足。"},
        ],
        "3.2 完形填空与语法填空": [
            {"t": "完形填空解题策略", "body": "**先快速通读全文把握大意，再逐空作答**。\n注意前后语境的逻辑关系。\n关注复现词（同义、反义、同根词）。\n常识与文化背景也有帮助。\n做完后再通读一遍检查连贯性。"},
            {"t": "语法填空", "body": "有提示词：注意词性转换与形式变化。\n无提示词：多考冠词、介词、连词、代词。\n**括号内动词要判断作谓语还是非谓语**。\n名词注意单复数，形容词注意比较级。\n大小写与拼写错误一律不得分。"},
            {"t": "短文改错", "body": "常见错误：多词、缺词、错词。\n**考点集中在冠词、介词、时态、主谓一致、非谓语**。\n每句一般只有一处错误。\n修改符号要规范：加、删、改。\n注意固定搭配与逻辑关系错误。"},
            {"t": "完形填空的复现技巧", "body": "完形填空常考查词汇复现，包括原词复现、同义复现、反义复现。\n做题时注意前后文反复出现的关键词。\n**同义复现：用不同词表达相同或相近的意思**。\n反义复现：前后文形成对比，提示答案。\n做完后通读全文，检查答案是否符合语境和逻辑。"},
            {"t": "完形填空的情感线索", "body": "完形填空要把握文章的情感线索。\n注意表示情感变化的词语。\n**情感线索帮助判断空格处的用词**。\n注意人物心情的前后变化。\n结合情感基调选择最恰当的答案。"},
            {"t": "完形填空的逻辑关系", "body": "完形填空要注意句子间的逻辑关系。\n**转折关系：but、however、although**。\n因果关系：because、so、therefore。\n递进关系：besides、moreover。\n对比关系：while、on the contrary。"},
            {"t": "完形填空的固定搭配", "body": "完形填空常考固定搭配。\n如动词短语、介词短语、形容词短语。\nlook forward to、be used to、take part in。\n**掌握常见固定搭配有助于快速解题**。\n平时多积累固定搭配和习惯用法。"},
            {"t": "语法填空的考点分布", "body": "有提示词：考查词性转换（名、动、形、副）、非谓语动词、时态语态、比较级。\n无提示词：多填介词、冠词、代词、连词、关系词。\n判断依据：空格前后的词性与句子结构。\n固定搭配与习惯用法要靠积累，如 in addition to、be responsible for。\n**每空只填一词（少数情况填两词），注意大小写**。"},
        ],
        "3.3 听力与书写规范": [
            {"t": "听力笔记与干扰项排除", "body": "边听边记关键词，用缩写与符号提高记录速度。\n注意数量信息与对应单位的匹配。\n**干扰项常是原文出现但不符合题意的信息**。\n注意说话人的语气与言外之意。\n对话题要抓住人物关系与谈话目的。"},
            {"t": "听力理解的关键技巧", "body": "**听力播放前先浏览题目和选项，预测对话内容和问题**。\n注意转折词 but、however，答案常在转折之后。\n注意数字、时间、地点、人物关系等细节信息。\n听不清个别词不要停留，跟上语流抓住大意。\n第二遍听时重点核对不确定的信息，快速做出选择。"},
            {"t": "听力高频场景词汇", "body": "餐厅：menu /ˈmenjuː/、order /ˈɔːdə(r)/、reserve /rɪˈzɜːv/、bill /bɪl/、tip /tɪp/。\n机场与车站：boarding pass /ˈbɔːdɪŋ pɑːs/、delay /dɪˈleɪ/、platform /ˈplætfɔːm/、one-way ticket /ˌwʌnˈweɪ ˈtɪkɪt/。\n医院：appointment /əˈpɔɪntmənt/、symptom /ˈsɪmptəm/、prescription /prɪˈskrɪpʃn/、take medicine /teɪk ˈmedsn/。\n学校：lecture /ˈlektʃə(r)/、assignment /əˈsaɪnmənt/、deadline /ˈdedlaɪn/、scholarship /ˈskɒləʃɪp/。\n购物：discount /ˈdɪskaʊnt/、refund /ˈriːfʌnd/、try on /traɪ ɒn/、**out of stock** /ˌaʊt əv ˈstɒk/。"},
            {"t": "卷面与书写规范要点", "body": "字母大小写规范：句首、专有名词、标题实词首字母大写。\n字迹清晰、间距均匀，避免涂改与大段划掉。\n书面表达分段清晰，一般三段：开头点题、主体展开、结尾总结。\n标点用英文标点：句号用实心点，逗号后空一格。\n**控制词数，写在答题区域内，超出部分无效**。"},
            {"t": "听力的人物关系判断", "body": "听力中判断人物关系。\n**根据称呼和用语判断**。\n如师生、医患、服务员顾客、同事、夫妻。\n人物关系帮助理解对话。\n注意称呼词和场景词。\n语气也能提示关系：正式还是随意。"},
            {"t": "听力的地点判断", "body": "听力中判断对话发生的地点。\n根据关键词判断，如 menu /ˈmenjuː/、order /ˈɔːdə(r)/ 提示餐厅。\ndoctor /ˈdɒktə(r)/、medicine /ˈmedsn/、fever /ˈfiːvə(r)/ 提示医院。\nclass /klɑːs/、exam /ɪɡˈzæm/ 提示学校，flight /flaɪt/、board /bɔːd/ 提示机场。\n**地点题是听力常考题型**。"},
            {"t": "听力的推理判断", "body": "听力中要能进行推理判断。\n根据说话人的语气判断态度。\n根据上下文推断对话含义。\n判断对话发生的场景和人物关系。\n**推理要基于听到的信息，不能凭空猜测**。\n注意言外之意和隐含信息。"},
            {"t": "数字与时间信息的记录", "body": "听力中的数字题常考价格、时间、日期、电话号码，必须边听边记阿拉伯数字。\n价格常出现干扰项，注意 half price、discount、twenty percent off、for two 等表述。\n**时间题注意 past 与 to 的区别**：a quarter past nine 是九点一刻，a quarter to nine 是八点三刻。\n日期注意英式与美式顺序不同，英式日/月/年，美式月/日/年。\n听清疑问词再作答：how much 问价格，how long 问时长，how often 问频率，when 问时间点。\n数字题往往需要简单运算，如两人各买一张则要乘二。"},
        ],
    },
    "第四板块 写作": {
        "4.1 应用文写作": [
            {"t": "常见应用文体裁", "body": "书信：开头 Dear…，结尾 Yours sincerely。\n通知：标题 Notice，正文说明时间地点事项。\n演讲稿：称呼、主题句、论证、号召。\n电子邮件：主题明确、正文简洁、结尾礼貌。\n**日记：日期、天气、正文，多用过去时**。"},
            {"t": "评分要点", "body": "**内容要点齐全，覆盖题目要求的全部信息点**。\n应用词汇和语法结构的数量与准确性，高级表达适当加分。\n上下文的连贯性，靠衔接词与指代保持顺畅。\n语言的得体性，称呼与语气要符合文体和对象。\n书写规范、字数达标，一般 80 词左右。"},
            {"t": "书信类应用文格式", "body": "书信格式包含称呼、正文、结束语、署名和日期五部分。\n称呼顶格写，后用逗号；正文每段开头可缩进。\n**结束语常用 Yours sincerely（熟人）/ Yours faithfully（正式）**。\n正文开头常用 I am writing to... 表明写作目的。\n结尾常用 Looking forward to your reply 表达期待。"},
            {"t": "通知类应用文的写法", "body": "**通知类应用文要先写标题 Notice，再写正文**。\n正文开头交代事由，用 We are going to... 等句式。\n中间说明时间、地点、参加对象和具体要求。\n结尾表达期待，如 Please be on time / Everyone is welcome。\n落款写发布单位和日期，语言简洁、格式规范。"},
            {"t": "邀请信的写法", "body": "**邀请信开头说明写信目的**，用 I am writing to invite you to...。\n正文说明活动的时间、地点和内容。\n表达期待对方参加，用 We would be honored if you could come。\n结尾用 Looking forward to your reply。\n语气要诚恳礼貌，格式规范。"},
            {"t": "感谢信的写法", "body": "**感谢信开头表达感谢**，用 I am writing to express my thanks for...。\n正文说明感谢的原因和具体事例。\n表达感激之情，如 I really appreciate your help。\n结尾再次感谢，用 Thanks again for your kindness。\n语气真诚，格式规范。"},
            {"t": "建议信的写法", "body": "建议信开头说明写信目的，用 I am writing to give some suggestions。\n正文提出建议，用 Firstly、Secondly 等连接词。\n**每条建议要具体、可行**。\n结尾表达希望建议被采纳，用 I hope my suggestions will be helpful。\n语气委婉，格式规范。"},
            {"t": "道歉信的写法", "body": "道歉信开头表达歉意，用 I am writing to apologize for...。\n正文说明原因并表达歉意。\n**提出补救措施**，用 I will make it up to you。\n结尾再次道歉，用 I sincerely apologize。\n语气诚恳，格式规范。"},
            {"t": "演讲稿的写法", "body": "演讲稿开头要有称呼和问候语。\n如 Good morning, everyone。\n正文提出观点，展开论述。\n用 First、Second 等连接词使结构清晰。\n**结尾发出号召**，用 Let's... 或 Thank you。"},
            {"t": "请假条的写法", "body": "请假条是向老师或领导请假的便条。\n**写明请假原因和天数**。\n语气诚恳，理由合理。\n格式有称呼、正文、落款（署名和日期）。\n请假条要简洁明了。\n常用开头 I am writing to ask for leave...，结尾表示感谢。"},
            {"t": "高分句式与衔接词", "body": "开篇句式：I am writing to inform you that...／It is a great pleasure to...\n衔接词：firstly、besides、what is more、however、as a result、in conclusion。\n高级结构：定语从句、非谓语作状语、倒装、强调句，适当使用提升档次。\n**避免全篇简单句堆砌，长短句结合**。\n结尾句式：I would appreciate it if you could...／Looking forward to your reply。"},
            {"t": "倡议书的写作要点", "body": "**倡议书要明确倡议目的，开头交代背景和意义**。\n正文分点说明倡议的具体内容，条理清晰。\n语言有感染力，能调动读者的积极性。\n结尾发出号召，表达期待和希望。\n倡议书格式规范，有标题、称呼、正文、落款。"},
            {"t": "投诉信的写法", "body": "投诉信开头说明投诉的问题，用 I am writing to complain about。\n正文描述问题的具体情况，包括时间、经过和影响。\n提出解决方案或合理要求，表达期待处理。\n**语气要礼貌而坚定，不卑不亢**。\n结尾用 I look forward to your reply，投诉信格式规范。"},
            {"t": "电子邮件的写作", "body": "电子邮件由主题、称呼、正文、结束语、署名组成。\n**主题行简洁明确，概括邮件内容**。\n称呼用 Dear...，正文简明扼要。\n语气要得体，根据对象调整。\n电子邮件格式规范，便于沟通。"},
            {"t": "申请信的写作", "body": "申请信是向对方申请职位或机会的书信。\n开头说明申请目的，用 I am writing to apply for。\n**正文介绍自己的情况、优势和申请理由**。\n表达对机会的重视和期待。\n结尾用 Looking forward to your reply 表达期待。"},
        ],
        "4.2 读后续写": [
            {"t": "常见问题与改进", "body": "**避免情节跳跃、逻辑断裂，两段之间要有承接句**。\n避免与原文内容重复照抄，续写必须有所发展。\n避免语法错误与中式英语，多用学过的固定搭配。\n字数控制在规定范围内，一般每段 60~80 词。\n书写工整、分段清晰，时态与原文保持一致。"},
            {"t": "读后续写的写作策略", "body": "读后续写要先读懂原文情节、人物和主题，再续写两段。\n**续写内容要与原文情节衔接自然，符合人物性格**。\n注意每段首句已给出，续写要围绕首句展开。\n描写要具体，用动作、心理、环境描写使故事生动。\n结尾要点题升华，与原文主题呼应，不要出现新人物新情节。"},
            {"t": "读后续写的语言表达", "body": "读后续写要用生动的语言描写，避免平铺直叙。\n多用动作描写和心理描写，让人物形象鲜活。\n适当使用非谓语动词和状语从句，使句子结构丰富。\n**注意时态一致，读后续写一般用过去时态**。\n段与段之间要有过渡，保持故事连贯流畅。"},
            {"t": "读后续写的环境描写", "body": "环境描写能烘托气氛、衬托人物心情。\n用感官描写（视觉、听觉、嗅觉）使环境生动。\n环境描写与故事情节和人物心情相呼应。\n如阴雨天烘托悲伤心情，阳光明媚烘托喜悦。\n**环境描写要简洁，不宜过多，服务主题**。"},
            {"t": "读后续写的人物塑造", "body": "读后续写要通过描写塑造人物形象。\n用动作描写表现人物行为，用心理描写表现内心。\n用语言描写表现人物性格，用外貌描写勾勒形象。\n**人物性格要与原文一致，不能前后矛盾**。\n通过人物在事件中的表现体现主题。"},
            {"t": "读后续写的主题把握", "body": "读后续写要准确把握原文的主题和情感。\n续写内容要与主题一致，不能跑题。\n主题通常与成长、亲情、友情、勇气等有关。\n**续写要传递积极向上的价值观**。\n结尾要点明主题，与原文呼应。"},
            {"t": "读后续写的对话描写", "body": "对话描写能推动情节发展、刻画人物。\n**对话要符合人物身份和性格**。\n用恰当的引语动词，如 said、replied、shouted。\n对话中穿插动作和神态描写，使画面生动。\n对话要简洁，避免冗长。"},
            {"t": "读后续写的语言衔接", "body": "读后续写要注意语言的连贯衔接。\n使用连接词：then、however、therefore。\n使用时间状语：soon、later、finally。\n段与段之间自然过渡。\n**保持时态一致和主语一致**。"},
            {"t": "读后续写的动作描写", "body": "动作描写要具体生动。\n用一连串动作表现人物行为。\n如 ran、jumped、grabbed 等动词。\n动作描写推动情节发展。\n**动作与心理描写结合，使人物鲜活**。"},
            {"t": "读后续写的细节描写", "body": "细节描写使故事生动具体。\n抓住人物、环境的细节。\n用具体的动作、神态、语言描写，多用动词。\n细节要服务主题，不堆砌。\n**好的细节描写增强感染力**。\n可调动视觉、听觉、触觉使场景真实。"},
            {"t": "读后续写的结尾技巧", "body": "读后续写的结尾要简洁有力。\n**结尾点明主题，升华中心**。\n与开头呼应，结构完整。\n可含蓄留白，引发思考。\n避免冗长拖沓的结尾。\n结尾常回归情感或感悟，一两句点睛即可。"},
            {"t": "读后续写的情节起伏", "body": "读后续写要有情节起伏，避免平铺直叙。\n**设置矛盾和冲突，使故事有张力**。\n情节发展要有转折，制造悬念吸引读者。\n高潮部分扣人心弦，冲突达到顶点。\n结尾解决矛盾，圆满收束，与开头呼应。"},
            {"t": "续写的情节构思", "body": "先读原文，把握人物关系、冲突与情感基调。\n找出伏笔与线索，让续写的情节与之呼应。\n**两段分工：第一段解决主要冲突，第二段收束情感与主题**。\n避免引入新人物或新的大事件，情节要合理可信。\n结尾要有情感升华或主题点题，但不能生硬说教。"},
            {"t": "读后续写的时间线索", "body": "读后续写要理清时间线索。\n**按时间顺序展开情节**，避免时间线混乱。\n注意时间状语的使用：later、the next day、after a while。\n时间线索保持连贯，续写与原文衔接自然。\n情节发展符合时间逻辑。\n用时间词分段推进，使层次清晰。"},
            {"t": "读后续写的伏笔", "body": "读后续写要注意伏笔。\n**原文的伏笔要在续写中呼应**。\n伏笔使故事前后照应。\n呼应伏笔使情节完整。\n注意原文细节的暗示：反复出现的物件、动作、话语。\n续写前先回读原文，圈出可呼应的细节。"},
            {"t": "读后续写的悬念设置", "body": "读后续写可以适当设置悬念。\n悬念能吸引读者，增强故事吸引力。\n常在段末设置悬念，引发读者兴趣。\n悬念推动情节发展，制造起伏。\n**悬念要在后续合理解决，前后照应**。"},
            {"t": "续写的高频情节模板", "body": "**读后续写的情节推进讲究「冲突—转折—解决—感悟」四步**。\n第一段通常承接原文悬念，写人物遇到困难或做出决定，末尾留一个转折点给第二段。\n第二段解决冲突，写出行动与结果，最后用一两句心理描写点出成长或感悟。\n常用情感线索：紧张—挣扎—释然，避免全程平铺直叙。\n动作与神态描写要具体，如 rushed、stared、let out a long breath、a lump rose in my throat。\n主题句要自然，从事件提炼道理，如 It was then that I realized kindness costs nothing but means everything."},
        ],
    },
}
